(5557,1785,'Velocidade 4',1,1.0000000,'Correto! Não exceda a velocidade 4 com a borboleta.',1),
(5558,1785,'Velocidade 8',1,0.0000000,'Incorreto.',1),
(5559,1786,'250 ml',1,0.0000000,'Incorreto. 250 ml evaporam-se em 15 minutos.',1),
(5560,1786,'500 ml (500 g)',1,1.0000000,'Correto! São necessários 0,5 litros para 30 minutos.',1),
(5561,1786,'750 ml',1,0.0000000,'Incorreto.',1),
(5562,1786,'1 litro',1,0.0000000,'Incorreto.',1),
(5563,1787,'Retirar o copo e transportá-lo separadamente.',1,0.0000000,'Incorreto.',1),
(5564,1787,'Ativar o Modo de transporte no menu, que bloqueia o copo.',1,1.0000000,'Correto! O Modo de transporte bloqueia o copo para evitar movimentos.',1),
(5565,1787,'Desligar da tomada e enrolar o cabo.',1,0.0000000,'Isso é necessário, mas não é o principal.',1),
(5566,1787,'Pressionar as barras de bloqueio para as fixar.',1,0.0000000,'Incorreto. Não empurre as barras.',1),
(5567,1788,'True',0,0.0000000,'Correto.',1),
(5568,1788,'False',0,1.0000000,'Falso. O manual adverte que não se deve mergulhar a lâmina em água durante muito tempo, pois pode danificar o sistema de juntas.',1),
(5569,1789,'5 minutos',1,0.0000000,'Incorreto.',1),
(5570,1789,'10 minutos',1,0.0000000,'Incorreto.',1),
(5571,1789,'15 minutos',1,1.0000000,'Correto! A Bimby desliga-se após 15 minutos de inatividade.',1),
(5572,1789,'30 minutos',1,0.0000000,'Incorreto.',1),
(5573,1790,'Se a lâmina está bem encaixada.',1,0.0000000,'Incorreto.',1),
